import{z as o,x as d,o as t,c as A,q as i,j as l,D as e,d as r,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const M=JSON.parse(`{"title":"Ellis-Michaely-O'Hara 改进","description":"","frontmatter":{"title":"Ellis-Michaely-O'Hara 改进","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/emo-trade-sign.md","filePath":"quant/emo-trade-sign.md","lastUpdated":1791413859000}`),B={name:"quant/emo-trade-sign.md"};function c(p,a,h,u,m,k){const E=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=i('<h1 id="ellis-michaely-o-hara-改进" tabindex="-1">Ellis-Michaely-O&#39;Hara 改进 <a class="header-anchor" href="#ellis-michaely-o-hara-改进" aria-label="Permalink to &quot;Ellis-Michaely-O&#39;Hara 改进&quot;">​</a></h1><div class="epigraph"><p>打在买一卖一上的成交，报价规则已经够用；困难集中在报价内侧。把内侧全部交给中点一侧的 Lee–Ready，会把本该用 tick 的成交误判。</p><footer>—— Ellis, Michaely and O&#39;Hara, The Accuracy of Trade Classification Rules, Journal of Financial and Quantitative Analysis, 2000</footer></div><p>附录微观结构续从方向分类补起。<a href="/quant/lee-ready">Lee-Ready</a> 用中点切开买卖，平价才用 tick。<a href="/quant/tick-quote-rule">Tick / Quote 规则</a>把两条规则拆开对照。Ellis、Michaely 与 O&#39;Hara（2000）用带真实主动标志的系统订单数据表明：报价规则在成交位于 bid/ask 时更准，tick 规则在中点附近相对不那么糟，组合整体最好——但他们建议的切法与 Lee–Ready <strong>不是同一刀</strong>。本课写这把刀：外侧用报价，<strong>内侧（含中点与价差内部）用 tick</strong>，以及它如何改变有效价差与 Huang–Stoll 输入。不重写两条规则的公式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lee–Ready 的报价检验是 \\(P\\gt M\\) 为买、\\(P\\lt M\\) 为卖。于是位于 \\((M,A)\\) 的成交——价格改善、优于中点但仍低于卖价——一律标成买。EMO 的经验是：这类内侧成交的真实主动方更混杂，用 tick 往往比用相对中点更好；真正干净的是打在 \\(A\\) 上的买和打在 \\(B\\) 上的卖。缺口是：默认算法把「不在中点」当成「报价已经足够」，EMO 把「不在 bid/ask」当成「应交给 tick」。在 \\(n=1\\) 的 tick 约束股票上，价差内部几乎只剩中点一格，两把刀收敛；在价差较宽或内部化很多时，两把刀分叉，方向序列不同，<a href="/quant/huang-stoll-spread">Huang-Stoll</a> 的 \\(\\theta\\) 会跟着走。</p><p>问题不是谁的正确率永远更高，而是按落点分层选规则，并报告分层覆盖。EMO 论文的贡献是分层证据，而不只是又一个全样本百分比。</p><p><span class="marginnote">「价差内部」就是成交价落在买价与卖价之间、没吃到挂牌报价的位置。比如买价 10.00、卖价 10.04，成交在 10.01–10.03 都算内侧，俗称「价格改善」——对手给了你比展示价更好的价格。内侧成交越多的市场，这把刀往哪边切就越要紧。</span></p><h3 id="操作性定义" tabindex="-1">操作性定义 <a class="header-anchor" href="#操作性定义" aria-label="Permalink to &quot;操作性定义&quot;">​</a></h3><p>记买价 \\(B\\)、卖价 \\(A\\)、中点 \\(M\\)。EMO 风格分类：</p><ul><li>\\(P=A\\)（或在卖价外侧）→ 买</li><li>\\(P=B\\)（或在买价外侧）→ 卖</li><li>否则（开区间 \\((B,A)\\)，含中点）→ tick 规则</li></ul><p>与 Lee–Ready 的差别集中在 \\((B,M)\\) 与 \\((M,A)\\)。Lee–Ready 在这里用报价检验；EMO 用 tick。外侧两侧一致。实现时必须定义「等于」：是否允许亚 tick、是否用保护报价还是本所报价。碎片化下 \\(P\\) 相对 SIP 的 \\(A\\) 可能「在内侧」，相对本所却在卖价上。报价源要锁死。</p><p><span class="marginnote">五秒滞后是 Lee–Ready 的历史补丁。EMO 评估的是分类规则本身。现代复制应用成交前最后有效报价，不要把五秒和 EMO 绑在一起。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在有主动标志的子样本上按落点分层：at-ask、at-bid、inside、outside。分别报告报价规则、tick 规则、Lee–Ready、EMO 的正确率与覆盖。期望模式来自 EMO：外侧报价规则胜，内侧 tick 相对较好，全样本组合胜但组合定义不同。没有标志时，用随后中点移动的符号做弱检验：标成买的成交之后中点应更常上涨——这不能当正确率，只能当两条规则分歧时谁更像冲击。</p><p>下游：有效价差 \\(\\mathrm{ES}=2D(P-M)\\) 在 EMO 下，内侧成交的 \\(D\\) 来自 tick，可能与 \\((P-M)\\) 的符号不一致，于是单笔 ES 可为负。这不是 bug：改善成交的符号本就更不确定。应分层报 ES，而不是把负 ES 洗掉。Huang–Stoll 输入换 EMO 后，\\(\\theta\\) 变化应作为敏感性，而不是作为「更真的逆向选择」。</p><p><span class="marginnote">数字实例：\\(B=10.00\\)、\\(A=10.04\\)、\\(M=10.02\\)，一笔改善成交 \\(P=10.01\\) 被 tick 标成买（\\(D=+1\\)），则单笔 \\(\\mathrm{ES}=2\\times 1\\times(10.01-10.02)=-0.02\\)。买得比中点还便宜导致负号出现，这恰恰说明成交有改善，不是分类器坏了。</span></p>',16)),(t(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20LR%0A%20%20E%5B%22%E5%86%85%E4%BE%A7%E6%96%B9%E5%90%91%20D%20%E5%88%A4%E9%94%99%22%5D%20--%3E%20S%5B%22%E5%B8%A6%E7%AC%A6%E5%8F%B7%E6%B5%81%E9%87%8F%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20S%20--%3E%20ES%5B%22%E5%8D%95%E7%AC%94%E6%9C%89%E6%95%88%E4%BB%B7%E5%B7%AE%20ES%20%E7%AC%A6%E5%8F%B7%E9%94%99%22%5D%0A%20%20S%20--%3E%20TH%5B%22Huang-Stoll%20theta%20%E4%BC%B0%E8%AE%A1%E6%BC%82%E7%A7%BB%22%5D%0A%20%20S%20--%3E%20OFI%5B%22OFI%20%E4%B8%8E%20lambda%20%E5%9B%9E%E5%BD%92%E6%9C%89%E5%81%8F%22%5D%0A%20%20L%5B%22%E6%8C%89%E8%90%BD%E7%82%B9%E5%88%86%E5%B1%82%E6%8A%A5%E5%91%8A%22%5D%20-.-%3E%7C%22%E9%9A%94%E7%A6%BB%E5%86%85%E4%BE%A7%E8%AF%AF%E5%B7%AE%22%7C%20ES%0A%20%20L%20-.-%3E%7C%22%E6%95%8F%E6%84%9F%E6%80%A7%E8%80%8C%E9%9D%9E%E9%87%8D%E4%BC%B0%22%7C%20TH%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="小数化之后内侧更厚" tabindex="-1">小数化之后内侧更厚 <a class="header-anchor" href="#小数化之后内侧更厚" aria-label="Permalink to &quot;小数化之后内侧更厚&quot;">​</a></h3><p>EMO 样本是纽约专家时代。小数化、内部化、中点 ATS 使内侧成交占比上升，分层变得更重要，而不是更不重要。把 2000 年的全样本 81% 正确率写进 2020 年代论文当精度，是引用不当。应在自己的场所与年代上重做分层表。官方主动标志优先；没有标志时声明用的是哪一把刀。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>外侧成交的几何硬：主动买打在卖价，是 taker 吃展示流动性。内侧成交的生成过程杂：价格改善、隐藏单、零售批发、暗池打印到磁带。相对中点的符号不再等于主动方。tick 规则用价格序列的局部动量当代理，在内侧的混杂过程里有时更稳，因为它不依赖一个可能过时或含零股的 \\(M\\)。这不是理论最优，是经验分层。机制上，方向误差进入所有「带符号流量」：OFI、lambda、PIN 计数、实现价差。EMO 的改进是减少内侧的系统性误判，不是消灭误差。</p><p><span class="marginnote">不要用 EMO 去「修正」集合竞价成交。拍卖没有 bid/ask 落点这套几何。方向应来自不平衡，见开盘课。</span></p>',5)),(t(),l(s,null,{default:e(()=>[n(E,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TB%0A%20%20P%5B%22%E6%88%90%E4%BA%A4%E4%BB%B7%20P%22%5D%20--%3E%20OUT%5B%22P%20%E5%9C%A8%20bid%2Fask%20%E5%A4%96%E4%BE%A7%22%5D%0A%20%20P%20--%3E%20IN%5B%22P%20%E5%9C%A8%E4%BB%B7%E5%B7%AE%E5%86%85%E9%83%A8%22%5D%0A%20%20OUT%20--%3E%20Q%5B%22%E6%8A%A5%E4%BB%B7%E8%A7%84%E5%88%99%22%5D%0A%20%20IN%20--%3E%20T%5B%22tick%20%E8%A7%84%E5%88%99%22%5D%0A%20%20Q%20--%3E%20D%5B%22%E6%96%B9%E5%90%91%20D%22%5D%0A%20%20T%20--%3E%20D%0A%20%20LR%5B%22Lee-Ready%EF%BC%9A%E4%BB%A5%E4%B8%AD%E7%82%B9%E5%88%87%E5%BC%80%22%5D%20-.-%3E%7C%22%E5%86%85%E4%BE%A7%E4%B8%8D%E5%90%8C%22%7C%20D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">直觉类比：方向分类像看脚印猜来人去向。外侧成交像笔直指向大门的脚印，一眼可断；内侧成交像大厅里徘徊的脚印，用「下一步往哪挪」（tick）猜，常比拿「大厅中线」（中点）当参照更靠谱——但终究是猜，所以要分层报告命中率，而不是装作全对。</span></p><h3 id="内侧成交的有效价差应为负仍要保留" tabindex="-1">内侧成交的有效价差应为负仍要保留 <a class="header-anchor" href="#内侧成交的有效价差应为负仍要保留" aria-label="Permalink to &quot;内侧成交的有效价差应为负仍要保留&quot;">​</a></h3><p>EMO 在内侧用 tick，\\(D\\) 与 \\((P-M)\\) 可以异号，单笔 ES 为负。这是改善成交的不确定性，不是脏数据。分层报告，不要把负 ES 洗成缺失。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>期货只有成交打印时，EMO 退化为 tick，没有改进。债券 OTC 没有 BBO 落点，不适用。加密若有明确的 taker 标志，应直接用标志，规则分类是退化。本附录后续 BVC 是桶上分类，不要与 EMO 逐笔比正确率。</p><p><span class="marginnote">没有主动标志时，用随后中点符号只能做弱检验。它不能把 EMO 的正确率从 2000 年表格搬进你的样本。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EMO 在 bid/ask 用报价，在价差内部用 tick；Lee–Ready 用中点切开。</li><li>差别在 \\((B,A)\\) 开区间；一 tick 价差时两刀收敛。</li><li>必须按落点分层报告，全样本正确率会掩盖内侧错误。</li><li>方向一换，有效价差与 Huang–Stoll 份额都要做敏感性。</li><li>现代内侧成交更多，分层比 2000 年更要紧。</li><li>出处：Ellis, Michaely and O&#39;Hara, <em>JFQA</em>, 2000；Lee and Ready, <em>Journal of Finance</em>, 1991。</li></ul>',8))])}const S=o(B,[["render",c]]);export{M as __pageData,S as default};
